import{Et as e,Gt as t,Tt as n,n as r}from"./chunks/framework.D88M5COo.js";var i=JSON.parse(`{"title":"Zotero Locale File","description":"Locale File：​ 这篇文档描述了如何帮助改进 CSL 样式的语言支持，主要是将 CSL locale file 翻译为需要的语言。","frontmatter":{"title":"Locale File","date":"2022-08-02T16:02:13.000Z","updated":"2022-08-03T10:17:57.000Z","description":"Locale File：​ 这篇文档描述了如何帮助改进 CSL 样式的语言支持，主要是将 CSL locale file 翻译为需要的语言。"},"headers":[],"relativePath":"csl-dev-guide/translating-locale-files.md","filePath":"wiki/csl-dev-guide/translating-locale-files.md","git":{"contributors":[{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"}],"changelog":[{"hash":"43e9d0ffbce770c9175de4c929f12fa5252a3d66","time":1714804981000,"message":"refactor: migrate SSG to VitePress, migrate website to zotero-chinese/website repo (<a href=\\"https://github.com/zotero-chinese/wiki/issues/172\\" target=\\"_blank\\" rel=\\"noreferrer\\">#172</a>)","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/43e9d0ffbce770c9175de4c929f12fa5252a3d66"},{"hash":"250ca63eb7e24bb552a69b15c4569be882e5215f","time":1701864530000,"message":"启用RSS，更新依赖 (<a href=\\"https://github.com/zotero-chinese/wiki/issues/108\\" target=\\"_blank\\" rel=\\"noreferrer\\">#108</a>)","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/250ca63eb7e24bb552a69b15c4569be882e5215f"},{"hash":"dce7f7a7fa167ff425bd0b5f331b8b7a8fea28c8","time":1701324765000,"message":"维护：增加Prettier和Git Hooks (<a href=\\"https://github.com/zotero-chinese/wiki/issues/107\\" target=\\"_blank\\" rel=\\"noreferrer\\">#107</a>)","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/dce7f7a7fa167ff425bd0b5f331b8b7a8fea28c8"},{"hash":"e8e86eff4d7817470a18a090062661321dcef1d5","time":1695483494000,"message":"Fix lint (<a href=\\"https://github.com/zotero-chinese/wiki/issues/19\\" target=\\"_blank\\" rel=\\"noreferrer\\">#19</a>)","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/e8e86eff4d7817470a18a090062661321dcef1d5"},{"hash":"ccd1ca00d97c3922c64382ec86c0d885c05b3d93","time":1690031195000,"message":"合入 csl 文档，暂存","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/ccd1ca00d97c3922c64382ec86c0d885c05b3d93"}]}}`),a={name:`csl-dev-guide/translating-locale-files.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="locale-file" tabindex="-1">Locale File <a class="header-anchor" href="#locale-file" aria-label="Permalink to “Locale File”">​</a></h1><div class="warning custom-block github-alert"><p class="custom-block-title">警告</p><p>此页面正在施工中。</p></div><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p>​ 这篇文档描述了如何帮助改进 CSL 样式的语言支持，主要是将 CSL locale file 翻译为需要的语言。</p><p>​ 用户总是会选择一个特定的语言环境或者 CSL 语言环境，例如：&quot;British Psychological Society&quot; 的 CSL 样式将会生成英式英语的引文和参考文献目录，中国使用的国标将会生成中文的引文和参考文献目录（可以有英文条目）。在使用的语言环境不是 CSL 定义的语言环境时，使用 Locale file 就会实现自动的本地化。</p><p>​ 所有的 CSL 样式，都依赖于 locale file，这些本地化文件中包含了本地化数据，用来指定引文和参考文献目录中的术语，日期格式和语法规则怎么本地化。在单独的本地化文件保存这些数据，而不是在 CSL 样式文件中（尽管 CSL 样式文件中可以使用 <code>cs:locale</code> 元素对本地化文件中的设置进行覆盖），有很多好处：1. 本地化更加容易维护；2. 样式文件更加的紧凑; 3. 样式可以是语言无关的。</p><p>​ 下面，我们将描述本地化文件的结构，给出如何转换所有部分的指示，并且解释如何提交这些转换。如果想获得更多的有关本地化的信息，可以查看 <a href="./specification">CSL 规范</a>。</p><h2 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to “开始”">​</a></h2><p>​ CSL 本地化文件在 GitHub 的仓库地址为<a href="https://github.com/citation-style-language/locales/" target="_blank" rel="noreferrer">https://github.com/citation-style-language/locales/</a>。</p><p>​ 每个本地化文件都包含一种对应语言的本地化数据。本地化文件的名字为 &quot;locales-xx-XX.xml&quot;，这里的 &quot;xx-XX&quot; 是 <a href="http://people.w3.org/rishida/utils/subtags/" target="_blank" rel="noreferrer">BCP 47 langues code 语言代码</a> 中的一种。这个 <a href="https://github.com/citation-style-language/locales/wiki" target="_blank" rel="noreferrer">GitHub wiki 仓库</a> 列出了本地化 code，对应的语言和该仓库中储存的所有语言环境的软换状态（是否完成，或在制作中）。</p><h2 id="转换-locale-files" tabindex="-1">转换 Locale Files <a class="header-anchor" href="#转换-locale-files" aria-label="Permalink to “转换 Locale Files”">​</a></h2><blockquote><p>todo</p></blockquote>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};